window.FTA_TOUR = {"slug":"drtoast-sunrise-epicycles","title":"Sunrise Epicycles","artist":"Dr. Toast","bpm":96,"key":"D Lydian","seconds":62.0,"group":"influences","how":"\"Radiant textures and beats to a sunrise near you\", as the project describes itself: a warm, widening sunrise over swung, glitchy beats, with shimmer on top. Written from that description and the science-titled catalogue, not from a record.","trick":"The melody is traced by epicycles: three circles turning on circles (Ptolemy's orbits, and a three-term Fourier series), read off as pitch in D Lydian.","stops":[{"t":0,"label":"Before dawn","text":"Before dawn: a dark pad."},{"t":10.0,"label":"First light: the beat","text":"First light: the swung beat and the bass arrive."},{"t":20.0,"label":"The epicycle melody","text":"The epicycle melody on plucks and bells."},{"t":40.0,"label":"Full sun","text":"Full sun: the pad has opened all the way."},{"t":55.0,"label":"Morning","text":"Morning."}],"checks":{"lufs":-14.0,"tp":-1.6,"clicks":0,"sha":"AA3E8D929BFF0AC5"},"gram":{"rows":72,"cols":620,"lo":"C1","fps":10,"b64":""},"videos":[{"t":0,"clip":"video/circles.mp4","label":"What does one circle secretly run?","page":"/circles.html"},{"t":10.0,"clip":"video/votes-as-rain.mp4","label":"Votes as rain","page":"/votes-as-rain.html"},{"t":20.0,"clip":"video/remix-sphere.mp4","label":"Points on a sphere","page":"/remix-sphere.html"},{"t":40.0,"clip":"video/way-of-water.mp4","label":"The Way of Water","page":"/way-of-water.html"},{"t":55.0,"clip":"video/circles.mp4","label":"What does one circle secretly run?","page":"/circles.html"}]};
